const onStrayError = (error) => {
	const text = String(error?.message || error);
	if (runtime) runtime.failInit(text);
	post({
		type: "log",
		level: "error",
		message: `uncaught: ${text.slice(0, 1e3)}`
	});
};
listen("error", (event) => {
	event.preventDefault();
	onStrayError(event.error || event.message);
});
listen("unhandledrejection", (event) => {
	event.preventDefault();
	onStrayError(event.reason);
});
listen("message", (event) => {
	onMessage(event.data);
});
//#endregion
